                "SELECT COUNT(*) FROM incident_agency_acks WHERE incident_id = ?"
                        + " AND config_version = ? AND ack_type = 'REJECT'",
                Integer.class, incidentId, version);
        return count != null && count > 0;
    }

    /**
     * 工具方法：解析机构代码 JSON（供需要处复用），空数组返回空列表。
     */
    public static List<String> parseCodes(String json) {
        if (json == null || json.isBlank()) {
            return List.of();
        }
        return Arrays.asList(json.replaceAll("[\\[\\]\"]", "").split(","));
    }
}

